function entries(rows: readonly Row[], collection: 'bukhari' | 'muslim', fridayOnly = false): ReminderEntry[] {
  return rows.map(([number, topic, meaningKey, quote, benefit, action]) => ({
    id: `${collection}-${number}`, topic, quote, benefit, action, meaningKey,
    hadithKey: `${collection}:${number.replace(/[a-z]+$/u, '')}`, fridayOnly,
    source: { collection, number, url: `https://sunnah.com/${collection}:${number}` },
    verifiedOn: '2026-10-23', attribution: number === '6039' ? 'عن عائشة رضي الله عنها في هديه ﷺ'
      : number === '5409' ? 'عن أبي هريرة رضي الله عنه في هديه ﷺ' : 'من الحديث النبوي ﷺ',
  }));
}
export const REMINDER_CATALOG: readonly ReminderEntry[] = Object.freeze([
  ...entries(bukhari, 'bukhari'), ...entries(muslim, 'muslim'), ...entries(friday, 'bukhari', true),
  ...entries([['854b','فضل الجمعة','friday-day','خير يوم طلعت عليه الشمس يوم الجمعة','ورد فضل يوم الجمعة في صحيح مسلم.','استثمر يومك في العبادة وصلة الأهل والعمل النافع.']], 'muslim', true),
]);

export function validateReminderCatalog(catalog: readonly ReminderEntry[] = REMINDER_CATALOG): string[] {
  const errors: string[] = [];
  const ids = new Set<string>();
  for (const entry of catalog) {
    if (ids.has(entry.id)) errors.push(`duplicate:${entry.id}`);
    ids.add(entry.id);
    if (!['bukhari','muslim'].includes(entry.source.collection) || !/^\d+[a-z]?$/u.test(entry.source.number)
      || entry.source.url !== `https://sunnah.com/${entry.source.collection}:${entry.source.number}`) errors.push(`source:${entry.id}`);
    if (!entry.quote || entry.quote.split(/\s+/u).length > 25 || !entry.benefit || !entry.action || !entry.meaningKey || !entry.hadithKey
      || !/^\d{4}-\d{2}-\d{2}$/u.test(entry.verifiedOn)) errors.push(`content:${entry.id}`);
  }
  return errors;
}
